def parse_insights(resp):
    out={}
    items=(((resp or {}).get('data') or {}).get('data') or [])
    for it in items:
        name=it.get('name')
        vals=it.get('values') or []
        if vals and isinstance(vals[0],dict):
            out[name]=vals[0].get('value')
        elif 'value' in it:
            out[name]=it.get('value')
    return out
